 14→func TestComputeFilesHash_Deterministic(t *testing.T) {
 15→	t.Parallel()
 16→
 17→	files := []string{"b.go", "a.go", "c.go"}
 18→	hash1 := computeFilesHash(files)
 19→	hash2 := computeFilesHash(files)
