 54→func TestWingmanPayload_RoundTrip(t *testing.T) {
 55→	t.Parallel()
 56→
 57→	payload := WingmanPayload{
 58→		SessionID:     "test-session-123",
 59→		RepoRoot:      "/tmp/repo",
 60→		BaseCommit:    "abc123def456",
 61→		ModifiedFiles: []string{"main.go", "util.go"},
 62→		NewFiles:      []string{"new.go"},
 63→		DeletedFiles:  []string{"old.go"},
 64→		Prompts:       []string{"Fix the bug", "Add tests"},
 65→		CommitMessage: "fix: resolve issue",
 66→	}
 67→
 68→	data, err := json.Marshal(payload)
 69→	if err != nil {
 70→		t.Fatalf("failed to marshal: %v", err)
 71→	}
 72→
 73→	var decoded WingmanPayload
 74→	if err := json.Unmarshal(data, &decoded); err != nil {
 75→		t.Fatalf("failed to unmarshal: %v", err)
 76→	}
 77→
 78→	if decoded.SessionID != payload.SessionID {
 79→		t.Errorf("session_id: got %q, want %q", decoded.SessionID, payload.SessionID)
 80→	}
 81→	if decoded.RepoRoot != payload.RepoRoot {
 82→		t.Errorf("repo_root: got %q, want %q", decoded.RepoRoot, payload.RepoRoot)
 83→	}
 84→	if decoded.BaseCommit != payload.BaseCommit {
 85→		t.Errorf("base_commit: got %q, want %q", decoded.BaseCommit, payload.BaseCommit)
 86→	}
 87→	if len(decoded.ModifiedFiles) != len(payload.ModifiedFiles) {
 88→		t.Errorf("modified_files: got %d, want %d", len(decoded.ModifiedFiles), len(payload.ModifiedFiles))
 89→	}
 90→	if len(decoded.NewFiles) != len(payload.NewFiles) {
 91→		t.Errorf("new_files: got %d, want %d", len(decoded.NewFiles), len(payload.NewFiles))
 92→	}
 93→	if len(decoded.DeletedFiles) != len(payload.DeletedFiles) {
 94→		t.Errorf("deleted_files: got %d, want %d", len(decoded.DeletedFiles), len(payload.DeletedFiles))
 95→	}
 96→	if len(decoded.Prompts) != len(payload.Prompts) {
 97→		t.Errorf("prompts: got %d, want %d", len(decoded.Prompts), len(payload.Prompts))
 98→	}
 99→	if decoded.CommitMessage != payload.CommitMessage {
100→		t.Errorf("commit_message: got %q, want %q", decoded.CommitMessage, payload.CommitMessage)
101→	}
102→}
